import { getStripe } from "@/lib/stripe";
import { getCurrentUser, setStripeCustomerId } from "@/lib/users";

export async function POST(request: Request) {
  const user = await getCurrentUser();
  if (!user) return new Response("Unauthorized", { status: 401 });
  if (user.plan === "pro") {
    return Response.redirect(new URL("/dashboard", request.url), 303);
  }

  const priceId = process.env.STRIPE_PRO_PRICE_ID;
  if (!priceId) return new Response("Billing is not configured", { status: 500 });

  const stripe = getStripe();
  const appUrl = process.env.APP_URL ?? new URL(request.url).origin;

  let customerId = user.stripeCustomerId;
  if (!customerId) {
    const customer = await stripe.customers.create({
      email: user.email,
      name: user.name,
      metadata: { userId: user.id },
    });
    customerId = customer.id;
    await setStripeCustomerId(user.id, customerId);
  }

  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    customer: customerId,
    client_reference_id: user.id,
    line_items: [{ price: priceId, quantity: 1 }],
    metadata: { userId: user.id },
    subscription_data: { metadata: { userId: user.id } },
    success_url: `${appUrl}/dashboard?checkout=success`,
    cancel_url: `${appUrl}/dashboard?checkout=cancelled`,
  });

  if (!session.url) return new Response("Could not create checkout session", { status: 502 });
  return Response.redirect(session.url, 303);
}
EOF
