import type Stripe from "stripe";
import { getStripe } from "@/lib/stripe";
import { getUserByStripeCustomerId, setPlan } from "@/lib/users";

export const runtime = "nodejs";

function customerIdOf(c: string | Stripe.Customer | Stripe.DeletedCustomer | null) {
  return typeof c === "string" ? c : c?.id;
}

export async function POST(request: Request) {
  const secret = process.env.STRIPE_WEBHOOK_SECRET;
  const signature = request.headers.get("stripe-signature");
  if (!secret || !signature) return new Response("Bad request", { status: 400 });

  // Signature verification needs the exact raw body.
  const body = await request.text();
  let event: Stripe.Event;
  try {
    event = getStripe().webhooks.constructEvent(body, signature, secret);
  } catch {
    return new Response("Invalid signature", { status: 400 });
  }

  switch (event.type) {
    case "checkout.session.completed": {
      const session = event.data.object;
      // Subscriptions with delayed payment methods complete before money moves.
      if (session.mode !== "subscription" || session.payment_status !== "paid") break;
      const userId = session.client_reference_id ?? session.metadata?.userId;
      const subscriptionId =
        typeof session.subscription === "string" ? session.subscription : session.subscription?.id;
      if (userId) await setPlan(userId, "pro", subscriptionId);
      break;
    }
    case "checkout.session.async_payment_succeeded": {
      const session = event.data.object;
      const userId = session.client_reference_id ?? session.metadata?.userId;
      const subscriptionId =
        typeof session.subscription === "string" ? session.subscription : session.subscription?.id;
      if (userId) await setPlan(userId, "pro", subscriptionId);
      break;
    }
    case "customer.subscription.deleted": {
      const customerId = customerIdOf(event.data.object.customer);
      const user = customerId ? await getUserByStripeCustomerId(customerId) : undefined;
      // Ignore stale events for a subscription that's no longer the user's current one.
      if (user && user.stripeSubscriptionId === event.data.object.id) await setPlan(user.id, "free");
      break;
    }
  }

  return new Response(null, { status: 200 });
}
EOF
